{"content":"import { createFileRoute, Link } from "@tanstack/react-router";
import { useCallback, useEffect, useMemo, useState } from "react";
import { toast } from "sonner";
import { supabase } from "@/integrations/supabase/client";
import { useAccess } from "@/hooks/useAccess";
import { usePricing } from "@/lib/pricing";

export const Route = createFileRoute("/admin/pricing")({
  head: () => ({
    meta: [
      { title: "Pricing Console | Pickrel Brothers Inc." },
      {
        name: "description",
        content:
          "Internal Pickrel Brothers pricing console: product cost, customer markups, special pricing, permissions and change history.",
      },
      { name: "robots", content: "noindex" },
      { property: "og:title", content: "Pricing Console | Pickrel Brothers Inc." },
      { property: "og:description", content: "Product cost, customer pricing rules and audit history." },
    ],
  }),
  component: PricingConsole,
});

interface ProductRow {
  id: string;
  slug: string;
  name: string;
  manufacturer: string | null;
  mfr_part_number: string | null;
  pickrel_sku: string | null;
  uom: string;
  availability: string;
  list_cost: number | null;
  cost_multiplier: number;
  net_cost: number | null;
  default_markup: number | null;
  cost_basis: number | null;
  active: boolean;
}

interface CustomerRow {
  id: string;
  name: string;
  account_number: string | null;
  default_markup: number | null;
  notes: string | null;
}

interface SpecialRow {
  id: string;
  customer_id: string;
  product_id: string | null;
  markup: number | null;
  negotiated_price: number | null;
  note: string | null;
}

interface AuditRow {
  id: string;
  actor_id: string | null;
  entity_type: string;
  entity_label: string | null;
  action: string;
  changes: Record<string, { from: unknown; to: unknown }>;
  created_at: string;
}

const TABS = ["products", "customers", "special", "settings", "access", "history"] as const;
type Tab = (typeof TABS)[number];
const TAB_LABEL: Record<Tab, string> = {
  products: "Product cost",
  customers: "Customers",
  special: "Special pricing",
  settings: "Default markup",
  access: "Permissions",
  history: "Change history",
};

const money = (v: number | null | undefined) =>
  v === null || v === undefined ? "—" : Number(v).toLocaleString("en-US", { style: "currency", currency: "USD" });

function PricingConsole() {
  const access = useAccess();
  const pricing = usePricing();
  const [tab, setTab] = useState<Tab>("products");

  if (access.loading) {
    return <div className="container-page py-16 text-sm text-muted-foreground">Checking access…</div>;
  }

  if (!access.user) {
    return (
      <Gate
        title="Sign in required"
        body="The pricing console is for Pickrel Brothers staff."
        cta={{ to: "/auth", label: "Sign in" }}
      />
    );
  }

  if (!access.isAdmin) {
    return (
      <Gate
        title="Admin access only"
        body="Your account doesn't have admin access. Only an authorized administrator can open the pricing console."
        cta={{ to: "/account", label: "Back to my account" }}
      />
    );
  }


  return (
    <div className="container-page py-10">
      <div className="flex flex-wrap items-end justify-between gap-3">
        <div>
          <h1 className="font-display text-3xl font-bold uppercase text-navy">Pricing Console</h1>
          <p className="mt-1 text-sm text-muted-foreground">
            {access.user.email} ·{" "}
            {access.isAdmin ? (
              <span className="font-semibold text-success">
                Admin{access.adminExpiresAt ? ` (temporary, until ${new Date(access.adminExpiresAt).toLocaleString()})` : ""}
              </span>
            ) : (
              <span className="font-semibold text-warning">Sales — view only</span>
            )}
          </p>
        </div>
        <button
          type="button"
          onClick={() => pricing.refresh()}
          className="rounded-md border border-input px-4 py-2 text-sm font-semibold text-navy hover:bg-secondary"
        >
          Recalculate live prices
        </button>
      </div>

      {!access.isAdmin && (
        <p className="mt-4 rounded-md bg-sky-soft p-3 text-sm text-navy">
          Sales accounts can view cost and pricing but cannot change it. Request temporary edit access
          under <button type="button" className="font-semibold underline" onClick={() => setTab("access")}>Permissions</button>.
        </p>
      )}

      <nav className="mt-6 flex flex-wrap gap-2 border-b border-border pb-3">
        {TABS.map((t) => (
          <button
            key={t}
            type="button"
            onClick={() => setTab(t)}
            className={`rounded-md px-3 py-1.5 text-sm font-semibold ${
              tab === t ? "bg-navy text-navy-foreground" : "text-navy hover:bg-secondary"
            }`}
          >
            {TAB_LABEL[t]}
          </button>
        ))}
      </nav>

      <div className="mt-6">
        {tab === "products" && <ProductsTab canEdit={access.isAdmin} onSaved={pricing.refresh} />}
        {tab === "customers" && <CustomersTab canEdit={access.isAdmin} onSaved={pricing.refresh} />}
        {tab === "special" && <SpecialTab canEdit={access.isAdmin} onSaved={pricing.refresh} />}
        {tab === "settings" && <SettingsTab canEdit={access.isAdmin} onSaved={pricing.refresh} />}
        {tab === "access" && <AccessTab access={access} />}
        {tab === "history" && <HistoryTab />}
      </div>
    </div>
  );
}

function Gate({ title, body, cta }: { title: string; body: string; cta: { to: string; label: string } }) {
  return (
    <div className="container-page py-16 text-center">
      <h1 className="font-display text-3xl font-bold uppercase text-navy">{title}</h1>
      <p className="mt-3 text-muted-foreground">{body}</p>
      <Link
        to={cta.to}
        className="mt-6 inline-block rounded-md bg-navy px-6 py-3 font-display font-bold uppercase tracking-wide text-navy-foreground hover:bg-navy-muted"
      >
        {cta.label}
      </Link>
    </div>
  );
}

const num = (v: string): number | null => (v.trim() === "" ? null : Number(v));

/* ------------------------------- Products ------------------------------ */

function ProductsTab({ canEdit, onSaved }: { canEdit: boolean; onSaved: () => void }) {
  const [rows, setRows] = useState<ProductRow[]>([]);
  const [guestMarkup, setGuestMarkup] = useState(1.45);
  const [filter, setFilter] = useState("");
  const [loading, setLoading] = useState(true);

  const load = useCallback(async () => {
    setLoading(true);
    const [{ data, error }, settings] = await Promise.all([
      supabase.from("products").select("*").order("name"),
      supabase.from("pricing_settings").select("guest_markup").maybeSingle(),
    ]);
    if (error) toast.error(error.message);
    setRows((data ?? []) as unknown as ProductRow[]);
    if (settings.data) setGuestMarkup(Number(settings.data.guest_markup));
    setLoading(false);
  }, []);

  useEffect(() => {
    void load();
  }, [load]);

  const visible = useMemo(() => {
    const q = filter.trim().toLowerCase();
    if (!q) return rows;
    return rows.filter((r) =>
      [r.name, r.manufacturer, r.mfr_part_number, r.pickrel_sku, r.slug]
        .filter(Boolean)
        .some((v) => String(v).toLowerCase().includes(q)),
    );
  }, [rows, filter]);

  async function save(row: ProductRow) {
    const { error } = await supabase
      .from("products")
      .update({
        name: row.name,
        manufacturer: row.manufacturer,
        mfr_part_number: row.mfr_part_number,
        pickrel_sku: row.pickrel_sku,
        uom: row.uom,
        availability: row.availability,
        list_cost: row.list_cost,
        cost_multiplier: row.cost_multiplier,
        net_cost: row.net_cost,
        default_markup: row.default_markup,
        active: row.active,
      })
      .eq("id", row.id);
    if (error) {
      toast.error(error.message);
      return;
    }
    toast.success("Saved", { description: row.name });
    await load();
    onSaved();
  }

  if (loading) return <p className="text-sm text-muted-foreground">Loading products…</p>;

  return (
    <div>
      <div className="flex flex-wrap items-center justify-between gap-3">
        <input
          value={filter}
          onChange={(e) => setFilter(e.target.value)}
          placeholder="Filter by name, part number or SKU"
          className="h-10 w-full max-w-sm rounded-md border border-input bg-card px-3 text-sm"
        />
        <p className="text-xs text-muted-foreground">
          Cost basis = net cost, or list cost × multiplier. Guest price = cost basis ×{" "}
          {guestMarkup} unless the product or customer sets its own markup.
        </p>
      </div>

      <div className="mt-4 space-y-3">
        {visible.map((row) => (
          <ProductEditor
            key={row.id}
            row={row}
            canEdit={canEdit}
            guestMarkup={guestMarkup}
            onSave={save}
          />
        ))}
        {visible.length === 0 && <p className="text-sm text-muted-foreground">No products match.</p>}
      </div>
    </div>
  );
}

function ProductEditor({
  row,
  canEdit,
  guestMarkup,
  onSave,
}: {
  row: ProductRow;
  canEdit: boolean;
  guestMarkup: number;
  onSave: (r: ProductRow) => Promise<void>;
}) {
  const [draft, setDraft] = useState<ProductRow>(row);
  useEffect(() => setDraft(row), [row]);

  const costBasis =
    draft.net_cost !== null && draft.net_cost !== undefined
      ? Number(draft.net_cost)
      : draft.list_cost !== null && draft.list_cost !== undefined
        ? Number(draft.list_cost) * Number(draft.cost_multiplier || 1)
        : null;
  const sell = costBasis === null ? null : costBasis * Number(draft.default_markup ?? guestMarkup);
  const dirty = JSON.stringify(draft) !== JSON.stringify(row);

  const field = (label: string, key: keyof ProductRow, type: "text" | "number" = "text") => (
    <label className="block text-xs font-semibold uppercase tracking-wide text-muted-foreground">
      {label}
      <input
        type={type}
        step="any"
        disabled={!canEdit}
        value={draft[key] === null || draft[key] === undefined ? "" : String(draft[key])}
        onChange={(e) =>
          setDraft({
            ...draft,
            [key]: type === "number" ? num(e.target.value) : e.target.value,
          })
        }
        className="mt-1 block w-full rounded-md border border-input bg-card px-2 py-1.5 text-sm font-normal normal-case text-foreground disabled:opacity-70"
      />
    </label>
  );

  return (
    <article className="rounded-md border border-border bg-card p-4 shadow-card">
      <div className="flex flex-wrap items-baseline justify-between gap-2">
        <h3 className="font-semibold text-navy">{row.name}</h3>
        <p className="font-mono text-xs text-muted-foreground">{row.slug}</p>
      </div>
      <div className="mt-3 grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
        {field("Product name", "name")}
        {field("Manufacturer", "manufacturer")}
        {field("MFR part #", "mfr_part_number")}
        {field("Pickrel SKU", "pickrel_sku")}
        {field("List cost", "list_cost", "number")}
        {field("Multiplier on list", "cost_multiplier", "number")}
        {field("Net cost (direct)", "net_cost", "number")}
        {field("Product markup (optional)", "default_markup", "number")}
        {field("UOM", "uom")}
        {field("Availability", "availability")}
      </div>
      <div className="mt-3 flex flex-wrap items-center gap-4 border-t border-border pt-3 text-sm">
        <span className="text-muted-foreground">
          Cost basis: <strong className="text-foreground">{money(costBasis)}</strong>
        </span>
        <span className="text-muted-foreground">
          Guest/list price: <strong className="text-foreground">{money(sell)}</strong>
        </span>
        {canEdit && (
          <button
            type="button"
            disabled={!dirty}
            onClick={() => void onSave(draft)}
            className="ml-auto rounded-md bg-navy px-4 py-2 text-sm font-semibold text-navy-foreground hover:bg-navy-muted disabled:opacity-40"
          >
            Save changes
          </button>
        )}
      </div>
    </article>
  );
}

/* ------------------------------ Customers ------------------------------ */

function CustomersTab({ canEdit, onSaved }: { canEdit: boolean; onSaved: () => void }) {
  const [rows, setRows] = useState<CustomerRow[]>([]);
  const [name, setName] = useState("");
  const [account, setAccount] = useState("");
  const [markup, setMarkup] = useState("");

  const load = useCallback(async () => {
    const { data, error } = await supabase.from("customers").select("*").order("name");
    if (error) toast.error(error.message);
    setRows((data ?? []) as unknown as CustomerRow[]);
  }, []);

  useEffect(() => {
    void load();
  }, [load]);

  async function add() {
    if (!name.trim()) return;
    const { error } = await supabase.from("customers").insert({
      name: name.trim(),
      account_number: account.trim() || null,
      default_markup: num(markup),
    });
    if (error) { toast.error(error.message); return; }
    setName("");
    setAccount("");
    setMarkup("");
    toast.success("Customer added");
    await load();
    onSaved();
  }

  async function update(row: CustomerRow, patch: Partial<CustomerRow>) {
    const { error } = await supabase.from("customers").update(patch).eq("id", row.id);
    if (error) { toast.error(error.message); return; }
    toast.success("Customer updated");
    await load();
    onSaved();
  }

  return (
    <div>
      {canEdit && (
        <div className="rounded-md border border-border bg-card p-4 shadow-card">
          <h3 className="font-display text-lg font-bold uppercase text-navy">Add customer account</h3>
          <div className="mt-3 grid gap-3 sm:grid-cols-4">
            <input value={name} onChange={(e) => setName(e.target.value)} placeholder="Company name" className="h-10 rounded-md border border-input bg-card px-3 text-sm" />
            <input value={account} onChange={(e) => setAccount(e.target.value)} placeholder="Account #" className="h-10 rounded-md border border-input bg-card px-3 text-sm" />
            <input value={markup} onChange={(e) => setMarkup(e.target.value)} placeholder="Markup e.g. 1.25" className="h-10 rounded-md border border-input bg-card px-3 text-sm" />
            <button type="button" onClick={() => void add()} className="h-10 rounded-md bg-navy px-4 text-sm font-semibold text-navy-foreground hover:bg-navy-muted">
              Add
            </button>
          </div>
        </div>
      )}

      <ul className="mt-4 divide-y divide-border rounded-md border border-border bg-card shadow-card">
        {rows.map((c) => (
          <li key={c.id} className="flex flex-wrap items-center gap-3 px-5 py-4">
            <div className="min-w-[220px] flex-1">
              <p className="font-semibold text-foreground">{c.name}</p>
              <p className="font-mono text-xs text-muted-foreground">{c.account_number ?? "no account #"}</p>
            </div>
            <label className="text-xs font-semibold uppercase text-muted-foreground">
              Markup
              <input
                type="number"
                step="any"
                disabled={!canEdit}
                defaultValue={c.default_markup ?? ""}
                onBlur={(e) => {
                  const v = num(e.target.value);
                  if (v !== (c.default_markup === null ? null : Number(c.default_markup))) {
                    void update(c, { default_markup: v });
                  }
                }}
                className="ml-2 h-9 w-28 rounded-md border border-input bg-card px-2 text-sm font-normal text-foreground disabled:opacity-70"
              />
            </label>
          </li>
        ))}
        {rows.length === 0 && <li className="px-5 py-8 text-sm text-muted-foreground">No customer accounts yet.</li>}
      </ul>
    </div>
  );
}

/* --------------------------- Special pricing --------------------------- */

function SpecialTab({ canEdit, onSaved }: { canEdit: boolean; onSaved: () => void }) {
  const [rows, setRows] = useState<SpecialRow[]>([]);
  const [customers, setCustomers] = useState<CustomerRow[]>([]);
  const [products, setProducts] = useState<ProductRow[]>([]);
  const [customerId, setCustomerId] = useState("");
  const [productId, setProductId] = useState("");
  const [markup, setMarkup] = useState("");
  const [price, setPrice] = useState("");
  const [note, setNote] = useState("");

  const load = useCallback(async () => {
    const [cpp, cust, prod] = await Promise.all([
      supabase.from("customer_product_pricing").select("*").order("created_at", { ascending: false }),
      supabase.from("customers").select("*").order("name"),
      supabase.from("products").select("*").order("name"),
    ]);
    setRows((cpp.data ?? []) as unknown as SpecialRow[]);
    setCustomers((cust.data ?? []) as unknown as CustomerRow[]);
    setProducts((prod.data ?? []) as unknown as ProductRow[]);
  }, []);

  useEffect(() => {
    void load();
  }, [load]);

  const customerName = (id: string) => customers.find((c) => c.id === id)?.name ?? id;
  const productName = (id: string | null) => (id ? (products.find((p) => p.id === id)?.name ?? id) : "All products");

  async function add() {
    if (!customerId) { toast.error("Pick a customer"); return; }
    const { error } = await supabase.from("customer_product_pricing").upsert(
      {
        customer_id: customerId,
        product_id: productId || null,
        markup: num(markup),
        negotiated_price: num(price),
        note: note.trim() || null,
      },
      { onConflict: "customer_id,product_id" },
    );
    if (error) { toast.error(error.message); return; }
    setMarkup("");
    setPrice("");
    setNote("");
    toast.success("Special pricing saved");
    await load();
    onSaved();
  }

  async function remove(id: string) {
    const { error } = await supabase.from("customer_product_pricing").delete().eq("id", id);
    if (error) { toast.error(error.message); return; }
    toast.success("Removed");
    await load();
    onSaved();
  }

  return (
    <div>
      {canEdit && (
        <div className="rounded-md border border-border bg-card p-4 shadow-card">
          <h3 className="font-display text-lg font-bold uppercase text-navy">Customer / product override</h3>
          <p className="mt-1 text-xs text-muted-foreground">
            Leave the product blank to override the whole account. A negotiated price wins over any markup.
            Product cost is never changed by these rules.
          </p>
          <div className="mt-3 grid gap-3 sm:grid-cols-5">
            <select value={customerId} onChange={(e) => setCustomerId(e.target.value)} className="h-10 rounded-md border border-input bg-card px-2 text-sm">
              <option value="">Customer…</option>
              {customers.map((c) => (
                <option key={c.id} value={c.id}>{c.name}</option>
              ))}
            </select>
            <select value={productId} onChange={(e) => setProductId(e.target.value)} className="h-10 rounded-md border border-input bg-card px-2 text-sm">
              <option value="">All products</option>
              {products.map((p) => (
                <option key={p.id} value={p.id}>{p.name}</option>
              ))}
            </select>
            <input value={markup} onChange={(e) => setMarkup(e.target.value)} placeholder="Markup" className="h-10 rounded-md border border-input bg-card px-3 text-sm" />
            <input value={price} onChange={(e) => setPrice(e.target.value)} placeholder="Negotiated price" className="h-10 rounded-md border border-input bg-card px-3 text-sm" />
            <button type="button" onClick={() => void add()} className="h-10 rounded-md bg-navy px-4 text-sm font-semibold text-navy-foreground hover:bg-navy-muted">
              Save rule
            </button>
          </div>
          <input value={note} onChange={(e) => setNote(e.target.value)} placeholder="Note (why this pricing exists)" className="mt-3 h-10 w-full rounded-md border border-input bg-card px-3 text-sm" />
        </div>
      )}

      <ul className="mt-4 divide-y divide-border rounded-md border border-border bg-card shadow-card">
        {rows.map((r) => (
          <li key={r.id} className="flex flex-wrap items-center gap-3 px-5 py-4 text-sm">
            <div className="min-w-[240px] flex-1">
              <p className="font-semibold text-foreground">{customerName(r.customer_id)}</p>
              <p className="text-xs text-muted-foreground">{productName(r.product_id)}</p>
              {r.note && <p className="text-xs italic text-muted-foreground">{r.note}</p>}
            </div>
            <span className="text-muted-foreground">Markup {r.markup ?? "—"}</span>
            <span className="text-muted-foreground">Negotiated {money(r.negotiated_price)}</span>
            {canEdit && (
              <button type="button" onClick={() => void remove(r.id)} className="text-sm font-semibold text-muted-foreground hover:text-destructive">
                Remove
              </button>
            )}
          </li>
        ))}
        {rows.length === 0 && <li className="px-5 py-8 text-sm text-muted-foreground">No special pricing rules yet.</li>}
      </ul>
    </div>
  );
}

/* ------------------------------- Settings ------------------------------ */

function SettingsTab({ canEdit, onSaved }: { canEdit: boolean; onSaved: () => void }) {
  const [value, setValue] = useState("");

  useEffect(() => {
    void supabase
      .from("pricing_settings")
      .select("guest_markup")
      .maybeSingle()
      .then(({ data }) => setValue(data ? String(data.guest_markup) : ""));
  }, []);

  async function save() {
    const v = num(value);
    if (v === null || v <= 0) { toast.error("Enter a markup greater than 0"); return; }
    const { error } = await supabase.from("pricing_settings").update({ guest_markup: v }).eq("id", true);
    if (error) { toast.error(error.message); return; }
    toast.success("Default markup updated");
    onSaved();
  }

  return (
    <div className="max-w-md rounded-md border border-border bg-card p-6 shadow-card">
      <h3 className="font-display text-lg font-bold uppercase text-navy">Guest / default markup</h3>
      <p className="mt-1 text-sm text-muted-foreground">
        Applied to visitors and to accounts with no markup of their own. 1.45 means cost × 1.45.
      </p>
      <input
        type="number"
        step="any"
        disabled={!canEdit}
        value={value}
        onChange={(e) => setValue(e.target.value)}
        className="mt-4 h-10 w-40 rounded-md border border-input bg-card px-3 text-sm disabled:opacity-70"
      />
      {canEdit && (
        <button type="button" onClick={() => void save()} className="ml-3 h-10 rounded-md bg-navy px-4 text-sm font-semibold text-navy-foreground hover:bg-navy-muted">
          Save
        </button>
      )}
    </div>
  );
}

/* ----------------------------- Permissions ----------------------------- */

interface ElevationRow {
  id: string;
  requested_by: string;
  reason: string;
  status: string;
  expires_at: string | null;
  created_at: string;
}

function AccessTab({ access }: { access: ReturnType<typeof useAccess> }) {
  const [requests, setRequests] = useState<ElevationRow[]>([]);
  const [reason, setReason] = useState("");
  const [hours, setHours] = useState("4");

  const load = useCallback(async () => {
    const { data } = await supabase
      .from("pricing_elevation_requests")
      .select("*")
      .order("created_at", { ascending: false });
    setRequests((data ?? []) as unknown as ElevationRow[]);
  }, []);

  useEffect(() => {
    void load();
  }, [load]);

  async function request() {
    if (!reason.trim()) { toast.error("Describe the change you need to make"); return; }
    const { error } = await supabase.from("pricing_elevation_requests").insert({
      requested_by: access.user!.id,
      reason: reason.trim(),
    });
    if (error) { toast.error(error.message); return; }
    setReason("");
    toast.success("Request sent to the admins");
    await load();
  }

  async function approve(row: ElevationRow) {
    const expires = new Date(Date.now() + Number(hours || 4) * 3600_000).toISOString();
    const grant = await supabase.from("user_roles").upsert(
      {
        user_id: row.requested_by,
        role: "admin",
        expires_at: expires,
        granted_by: access.user!.id,
        reason: row.reason,
      },
      { onConflict: "user_id,role" },
    );
    if (grant.error) { toast.error(grant.error.message); return; }
    const { error } = await supabase
      .from("pricing_elevation_requests")
      .update({ status: "approved", reviewed_by: access.user!.id, expires_at: expires })
      .eq("id", row.id);
    if (error) { toast.error(error.message); return; }
    toast.success(`Temporary edit access granted until ${new Date(expires).toLocaleString()}`);
    await load();
  }

  async function deny(row: ElevationRow) {
    const { error } = await supabase
      .from("pricing_elevation_requests")
      .update({ status: "denied", reviewed_by: access.user!.id })
      .eq("id", row.id);
    if (error) { toast.error(error.message); return; }
    await load();
  }

  return (
    <div className="space-y-6">
      {!access.isAdmin && (
        <div className="rounded-md border border-border bg-card p-5 shadow-card">
          <h3 className="font-display text-lg font-bold uppercase text-navy">Request temporary edit access</h3>
          <textarea
            rows={3}
            value={reason}
            onChange={(e) => setReason(e.target.value)}
            placeholder="e.g. Update special pricing for Miami Valley Mechanical on the 007-F5 circulator."
            className="mt-3 w-full rounded-md border border-input bg-card px-3 py-2 text-sm"
          />
          <button type="button" onClick={() => void request()} className="mt-3 rounded-md bg-navy px-4 py-2 text-sm font-semibold text-navy-foreground hover:bg-navy-muted">
            Send request
          </button>
        </div>
      )}

      {access.isAdmin && (
        <div className="rounded-md border border-border bg-card p-5 shadow-card">
          <h3 className="font-display text-lg font-bold uppercase text-navy">Grant window</h3>
          <label className="mt-2 block text-sm text-muted-foreground">
            Approvals grant admin rights for
            <input
              type="number"
              min={1}
              value={hours}
              onChange={(e) => setHours(e.target.value)}
              className="mx-2 h-9 w-20 rounded-md border border-input bg-card px-2 text-sm text-foreground"
            />
            hours, then expire automatically.
          </label>
        </div>
      )}

      <ul className="divide-y divide-border rounded-md border border-border bg-card shadow-card">
        {requests.map((r) => (
          <li key={r.id} className="flex flex-wrap items-center gap-3 px-5 py-4 text-sm">
            <div className="min-w-[260px] flex-1">
              <p className="font-semibold text-foreground">{r.reason}</p>
              <p className="text-xs text-muted-foreground">
                {new Date(r.created_at).toLocaleString()} · {r.status}
                {r.expires_at ? ` · expires ${new Date(r.expires_at).toLocaleString()}` : ""}
              </p>
            </div>
            {access.isAdmin && r.status === "pending" && (
              <div className="flex gap-2">
                <button type="button" onClick={() => void approve(r)} className="rounded-md bg-navy px-3 py-1.5 text-xs font-semibold text-navy-foreground hover:bg-navy-muted">
                  Approve
                </button>
                <button type="button" onClick={() => void deny(r)} className="rounded-md border border-input px-3 py-1.5 text-xs font-semibold text-muted-foreground hover:text-destructive">
                  Deny
                </button>
              </div>
            )}
          </li>
        ))}
        {requests.length === 0 && <li className="px-5 py-8 text-sm text-muted-foreground">No access requests.</li>}
      </ul>
    </div>
  );
}

