function HistoryTab() {
  const [rows, setRows] = useState<AuditRow[]>([]);
  const [emails, setEmails] = useState<Record<string, string>>({});

  useEffect(() => {
    void (async () => {
      const [{ data }, profiles] = await Promise.all([
        supabase.from("pricing_audit").select("*").order("created_at", { ascending: false }).limit(200),
        supabase.from("profiles").select("id, email"),
      ]);
      setRows((data ?? []) as unknown as AuditRow[]);
      const map: Record<string, string> = {};
      for (const p of profiles.data ?? []) map[p.id] = p.email ?? p.id;
      setEmails(map);
    })();
  }, []);

  const LABEL: Record<string, string> = {
    products: "Product",
    customers: "Customer",
    customer_product_pricing: "Special pricing",
    pricing_settings: "Default markup",
    user_roles: "Permissions",
  };

  return (
    <ul className="divide-y divide-border rounded-md border border-border bg-card shadow-card">
      {rows.map((r) => (
        <li key={r.id} className="px-5 py-4 text-sm">
          <div className="flex flex-wrap items-baseline justify-between gap-2">
            <p className="font-semibold text-foreground">
              {LABEL[r.entity_type] ?? r.entity_type} · {r.entity_label}
            </p>
            <p className="text-xs text-muted-foreground">
              {r.actor_id ? (emails[r.actor_id] ?? "staff") : "system"} · {new Date(r.created_at).toLocaleString()}
            </p>
          </div>
          <ul className="mt-1 space-y-0.5 text-xs text-muted-foreground">
            {Object.entries(r.changes ?? {}).map(([field, change]) => (
              <li key={field}>
                <span className="font-mono">{field}</span>: {String(change.from ?? "—")} → {String(change.to ?? "—")}
              </li>
            ))}
          </ul>
        </li>
      ))}
      {rows.length === 0 && <li className="px-5 py-8 text-sm text-muted-foreground">No changes recorded yet.</li>}
    </ul>
  );
}
